import{_ as a,o as r,c,a3 as i}from"./chunks/framework.Ch_0qWu9.js";const f=JSON.parse('{"title":"Graphviz corresponding-source offer","description":"","frontmatter":{"sourcePath":"assets/environments/lean-base/graphviz-epl/SOURCE-OFFER.md","sourceUrl":"https://github.com/MoonshotAI/TCSExam/blob/aab56977addd5d217972b7f35cf50be4440cb6c7/assets/environments/lean-base/graphviz-epl/SOURCE-OFFER.md","alternateUrl":"/TCSExam/docs/zh/environments/lean-base/graphviz-epl/SOURCE-OFFER/","alternateAnchors":{"graphviz-corresponding-source-offer":"graphviz-corresponding-source-offer","complete-source-archives":"complete-source-archives","modifications-and-build-rules":"modifications-and-build-rules","verification":"verification"}},"headers":[],"relativePath":"environments/lean-base/graphviz-epl/SOURCE-OFFER/index.md","filePath":"environments/lean-base/graphviz-epl/SOURCE-OFFER/index.md"}'),t={name:"environments/lean-base/graphviz-epl/SOURCE-OFFER/index.md"};function s(o,e,d,n,h,p){return r(),c("div",null,[...e[0]||(e[0]=[i(`<h1 id="graphviz-corresponding-source-offer" tabindex="-1">Graphviz corresponding-source offer <a class="header-anchor" href="#graphviz-corresponding-source-offer" aria-label="Permalink to &quot;Graphviz corresponding-source offer&quot;">​</a></h1><p>The Graphviz 15.0.0 program embedded in the ProofWidgets browser payloads is available under EPL-2.0. The complete corresponding source for Graphviz, the fixed wrapper source, the wrapper&#39;s Graphviz modifications, and the build rules accompany this image under <code>/usr/share/doc/tcsexam/graphviz-epl/</code>. Recipients can obtain these source materials directly from that directory without network access.</p><h2 id="complete-source-archives" tabindex="-1">Complete source archives <a class="header-anchor" href="#complete-source-archives" aria-label="Permalink to &quot;Complete source archives&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Installed archive</th><th>Official origin</th><th style="text-align:right;">Bytes</th><th>Verified SHA-256</th></tr></thead><tbody><tr><td>Graphviz 15.0.0</td><td><code>source/graphviz-15.0.0.tar.gz</code></td><td><a href="https://gitlab.com/graphviz/graphviz/-/archive/15.0.0/graphviz-15.0.0.tar.gz" target="_blank" rel="noreferrer">https://gitlab.com/graphviz/graphviz/-/archive/15.0.0/graphviz-15.0.0.tar.gz</a></td><td style="text-align:right;">41113527</td><td><code>dfa5be5c311f760aa9c88273c8f8101bb11f50b0de8b29bbd54acff3adc2d563</code></td></tr><tr><td><code>hpcc-js-wasm</code> commit <code>8b86e2f83cc7344aca44fb3d8aa29a227358c5c4</code></td><td><code>source/hpcc-js-wasm-8b86e2f83cc7344aca44fb3d8aa29a227358c5c4.tar.gz</code></td><td><a href="https://github.com/hpcc-systems/hpcc-js-wasm/archive/8b86e2f83cc7344aca44fb3d8aa29a227358c5c4.tar.gz" target="_blank" rel="noreferrer">https://github.com/hpcc-systems/hpcc-js-wasm/archive/8b86e2f83cc7344aca44fb3d8aa29a227358c5c4.tar.gz</a></td><td style="text-align:right;">455080</td><td><code>5443207dda2c30581e0632c8add206fcae3906f5faf20d4a0808499934743ee6</code></td></tr></tbody></table><p>The Graphviz archive also has SHA-512 <code>d69e2dd7b5127650b6e09de92508a84886d52d5dfd1eacf9e6abb797ca231db3c1b12546c7b8561e311150cd62be8dfea689021b7d139ffcdb3d4e16da670352</code>, exactly matching the value fixed in the wrapper&#39;s <code>vcpkg-overlays/graphviz/portfile.cmake</code>. The wrapper archive has SHA-512 <code>1a195429ba1d9d47803a78fc700c601ffcbd340d42b3c753f0f2a77cec4782768844b658227543bad7597ea5af553590c401a25ccc1aefea31a6b04f19e16a63</code>.</p><p>The source preparation command verifies the complete archives against the declared sizes and hashes. The Graphviz <code>LICENSE</code> member is installed as <code>EPL-2.0.txt</code>; the wrapper <code>LICENSE</code> member is installed as <code>WRAPPER-APACHE-2.0.txt</code>.</p><h2 id="modifications-and-build-rules" tabindex="-1">Modifications and build rules <a class="header-anchor" href="#modifications-and-build-rules" aria-label="Permalink to &quot;Modifications and build rules&quot;">​</a></h2><p>The wrapper archive is the fixed source for <code>@hpcc-js/wasm</code> 2.34.2. npm&#39;s version metadata identifies commit <code>8b86e2f83cc7344aca44fb3d8aa29a227358c5c4</code> as its <code>gitHead</code>.</p><p>The wrapper&#39;s <code>vcpkg-overlays/graphviz/portfile.cmake</code> replaces Graphviz&#39;s top-level <code>CMakeLists.txt</code> and <code>cmake/config_checks.cmake</code> with files from the overlay. It also replaces the <code>GVPLUGIN_CURRENT</code> and <code>GVPLUGIN_REVISION</code> substitutions described in that portfile. The exact files are present in the wrapper archive and as readable copies under <code>build-rules/vcpkg-overlays/graphviz/</code>.</p><p>The wrapper C++ entry point and support sources are under <code>build-rules/packages/graphviz/src-cpp/</code>. The wrapper build files select Emscripten SDK 6.0.0 and vcpkg 2026.06.01. Their official project locations are:</p><ul><li><a href="https://github.com/emscripten-core/emsdk" target="_blank" rel="noreferrer">https://github.com/emscripten-core/emsdk</a></li><li><a href="https://github.com/microsoft/vcpkg" target="_blank" rel="noreferrer">https://github.com/microsoft/vcpkg</a></li></ul><p>For a source rebuild, extract the wrapper archive into a writable directory and follow <code>build-rules/README.md</code>. The principal commands recorded by that fixed source are <code>npm ci</code>, <code>npm run install-build-deps</code>, and <code>npm run build</code>. The complete archive includes the build scripts and presets. Install the specified build tools and retain their applicable source and license materials alongside this Graphviz-specific archive set.</p><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>From the installed directory, run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/share/doc/tcsexam/graphviz-epl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sha256sum</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SHA256SUMS</span></span></code></pre></div><p><code>source-manifest.json</code> records the same versions, official URLs, archive sizes, and hashes in machine-readable form. Use the separate browser-component and npm inventories for the sources and notices of the image&#39;s other components.</p>`,16)])])}const b=a(t,[["render",s]]);export{f as __pageData,b as default};
